        // wow/flutter
        this._phase+=1/this._sr;
        const flutterAmt=Math.sin(this._phase*5.7)*flutter+Math.sin(this._phase*11.3)*flutter*0.3;
        let s=ic[i]*(1+flutterAmt);
        // drive + tape saturation (tanh approximation)
        s=s*drive;
        s=this._softclip(s, sat*2);
        // head-bump (subtle LF resonance)
        const bumpSample=s-this._bumpBuf[this._bumpPos];
